return {
    ["\n\n\n\n<InvHighlight>5月18日 晴</>\n　　<Hide stylename=\"InvDefault_HW\" id=\"#157\">秘偶</>是什么……\n\n\n\n"] = "\n\n\n\n<InvHighlight>May 18th, Sunny</>\n　　<Hide stylename=\"InvDefault_HW\" id=\"#157\">What is a marionette</>...\n\n\n\n",
    ["01-2_批量增加多种类道具"] = "01-2_Batch Add Multiple Types of Items",
    ["4.23查看蒙特利"] = "4.23 Check on Monterey",
    ["41 诊所"] = "41 Clinic",
    ["<Assistant_Title1>【吟游诗人】</>\n<Assistant_Title2>介绍:</>在各处探索时，偶尔会听到带有明确方向感的低语声在耳边回荡，循着声音逐步接近其来源，便可找到吟游诗人。\n<Assistant_Title2>玩法指引：</>\n<Assistant_Title3>1.寻找吟游诗人</>\n可通过以下任一方式前往吟游诗人：\n<Assistant_Property2>跑团入口：</>打开菜单进入【跑团】，加入任意教团后，在【秩序世界】中选择【吟游诗人】，点击【前往】即可自动寻路。\n<Assistant_Property1>地图入口：</>打开地图，切换至【探秘】页签，在地图中点击吟游诗人图标，即可追踪并自动寻路。\n<Assistant_Title3>2.聆听旋律</>\n到达目标地点后，跟随脚下的音波寻找声音来源，与吟游诗人对话，并选择对应的互动方式。\n<Assistant_Title3>3.完成挑战</>\n寻找旋律：开启<Assistant_System>灵视</>，寻找附近散落的三个音符，收集完成后即可开启奖励宝箱。\n哼唱旋律或解析旋律：根据提示完成投掷检定，检定成功即可完成挑战并获得奖励。"] = "<Assistant_Title1>【Bard】</>\n<Assistant_Title2>Introduction:</>When exploring various places, you will occasionally hear whispers with a clear sense of direction echoing in your ears. Follow the sound to gradually approach its source, and you will find the Bard.\n<Assistant_Title2>Gameplay Guide:</>\n<Assistant_Title3>1. Find the Bard</>\nYou can go to the Bard in any of the following ways:\n<Assistant_Property2>TRPG Entrance:</>Open the menu to enter 【TRPG】, join any sect, select 【Bard】 in the 【Order World】, and click 【Go】 to automatically pathfind.\n<Assistant_Property1>Map Entrance:</>Open the map, switch to the 【Exploration】 tab, click the Bard icon on the map to track and automatically pathfind.\n<Assistant_Title3>2. Listen to the Melody</>\nAfter arriving at the target location, follow the sound waves at your feet to find the source of the sound, talk to the Bard, and choose the corresponding interaction method.\n<Assistant_Title3>3. Complete the Challenge</>\nFind the melody: Turn on <Assistant_System>spirit vision</>, find the three musical notes scattered nearby, and after collecting them, you can open the reward chest.\nHum the melody or analyze the melody: Complete the throwing check according to the prompts; if the check is successful, you can complete the challenge and receive rewards.",
    ["<Assistant_Title1>【魔女的滋味真不错】</>\n<Assistant_Title2>任务类型：</><Assistant_Property2>支线</>\n<Assistant_Title2>任务描述：</>近日的廷根并不太平。作为值夜者小队的新人，你也被分派了一桩奇异的案件。而它指向的，是廷根北区的某个沙龙，以及留驻其中的神秘倩影……\n<Assistant_Title2>领取方式：</>扮演等级达到<Assistant_Red>50级</>后，可在任务面板手动领取\n<Assistant_Title2>任务奖励</>：认知经验、绑定苏勒、绑定金镑、历史明灯、装备、挂画·春夜之邀、双人·牵手"] = "<Assistant_Title1>【Taste of the Witch】</>\n<Assistant_Title2>Quest Type: </><Assistant_Property2>Side Quest</>\n<Assistant_Title2>Quest Description: </>Recent times in Tingen have not been peaceful. As a newcomer to the Nighthawks squad, you have been assigned a strange case. It points toward a certain salon in Tingen's North District and the mysterious beauty lingering within...\n<Assistant_Title2>How to Accept: </>Once your Acting Level reaches <Assistant_Red>50</>, you can manually accept it in the quest panel.\n<Assistant_Title2>Quest Rewards</>: Cognition EXP, Bound Sol, Bound Gold Pound, Historical Beacon, Equipment, Hanging Painting: Invitation of the Spring Night, Duo: Holding Hands",
    ["<Assistant_Title1>焚尽余香</>\n<Assistant_Title2>成就分类：</>跑团-城市暗面\n<Assistant_Title2>解锁条件：</>在罪恶廷根以“极佳”成绩完成：“激战邦尼”事件"] = "<Assistant_Title1>Burning Fragrance</>\n<Assistant_Title2>Achievement Category: </>TRPG-Dark Side of the City\n<Assistant_Title2>Unlock Condition: </>Complete the \"Fierce Battle with Bonnie\" event in Sinful Tingen with an \"Excellent\" rating",
    ["<Highlight>戴莉·西蒙妮</>，原廷根市值夜者小队队员，是阿霍瓦郡最有名的通灵者，因自行总结出扮演法导致晋升极快而被圣堂注意，后调往贝克兰德。她与邓恩队长的关系似乎非同一般。"] = "<Highlight>Daly Simone</>, a former member of the Tingen Nighthawks squad, is the most famous Spirit Medium in Awwa County. She was noticed by the Holy Cathedral because she summarized the Acting Method herself, leading to extremely fast advancement, and was later transferred to Backlund. Her relationship with Captain Dunn seems to be unusual.",
    ["<HyperLink stylename=\"M_Link\" u=\"86061110\" color=\"#f4a067\">巨剑斩击</>对命中目标打断0.5秒，输出形态下对敌人附加2秒沉默，并且额外加6秒<HighLight>衰败</>，对<HighLight>衰败</>状态的敌方造成的伤害增加<HighLight>10%</>。"] = "<HyperLink stylename=\"M_Link\" u=\"86061110\" color=\"#f4a067\">Greatsword Slash</> interrupts hit targets for 0.5 seconds. In Offensive Stance, it applies a 2-second silence to enemies, adds 6 seconds of <HighLight>Decay</>, and increases damage dealt to enemies in the <HighLight>Decay</> state by <HighLight>10%</>.",
    ["<HyperLink stylename=\"M_Link\" u=\"86071020\" color=\"#f4a067\">光之折射</>的伤害提高50%，额外获取10点<HighLight>神秘知识</>"] = "The damage of <HyperLink stylename=\"M_Link\" u=\"86071020\" color=\"#f4a067\">Refraction of Light</> is increased by 50%, and an additional 10 points of <HighLight>Secret Peeking</> are obtained.",
    ["<h>海莉</>的质问"] = "<h>Hayley's</> questioning",
    ["<h>跟随邓恩</>进入房间"] = "<h>Follow Dunn</> into the room",
    ["“剥面人”挑战%s第%s%s"] = "Face-Ripper Challenge %s No. %s %s",
    ["“头狼”鲁珀彻底疯狂，向你亮出了獠牙。"] = "Luper, the Alpha Wolf, has gone completely mad and bared his fangs at you.",
    ["“她像天使一般飞去了……”"] = "\"She flew away like an Angel...\"",
    ["……但抱歉，我真的想要回家。"] = "...But sorry, I really want to go home.",
    ["……噢，一点也不好，我的小猫在捉老鼠时摔进湖里淹死了。"] = "…Oh, it's not good at all, my kitten fell into the lake and drowned while catching a mouse.",
    ["　　随着<Highlight>罗塞尔大帝</>戏剧节临近，廷根各大报纸争相重温他的光辉历史。这位一百多年前的异国皇帝，曾推动工业革命的时代浪潮席卷北大陆各国。\n　　蒸汽轰鸣的时代，伟大的罗塞尔大帝的时代，仿佛又回来了！"] = "As the <Highlight> Emperor Roselle </> Drama Festival approaches, major newspapers in Tingen are competing to revisit his glorious history. This foreign emperor from over a hundred years ago once pushed the tides of the Industrial Revolution to sweep across the countries of the Northern Continent. \n The era of roaring steam, the era of the great Emperor Roselle, seems to have returned!",
    ["【44】怨恨"] = "【44】Resentment",
    ["一锅端-烂番茄个数"] = "One Pot Sweep - Rotten Tomato Count",
    ["不准再打伊琳的主意，明白吗？我明天会来看望伊琳的，她要是有什么问题……"] = "Don't you dare have any more designs on Irene, understand? I will come to visit Irene tomorrow. If she has any problems...",
